package com.aditya.search.service; import com.aditya.search.model.Document; import com.aditya.search.repo.DocumentRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class SearchService { private final DocumentRepository repo; public SearchService(DocumentRepository r){repo=r;} public Document add(Document d){return repo.save(d);} public List<Document> search(String q){return q==null||q.isBlank()?repo.findAll():repo.search(q);} public void delete(Long id){repo.deleteById(id);} }
